class AsyncFolders:
    """Folders for campaigns, audiences and accounts."""

    def __init__(self, client: AsyncSlideCold) -> None:
        self._client = client

    async def list(
        self,
        *,
        type: Optional[Literal['CAMPAIGN', 'AUDIENCE', 'ACCOUNT']] = None,
        parent_id: Optional[str] = None,
    ) -> List[FolderWithCounts]:
        """List folders.

        Required scope depends on `type`: CAMPAIGN → `campaigns:read`, AUDIENCE → `audiences:read`,
        ACCOUNT or omitted → `accounts:read`. Without `type`, folders of all types are returned. Returns
        root folders unless `parentId` is given.

        Scope: ``campaigns:read | audiences:read | accounts:read``. HTTP: ``GET /folders``.
        """
        return await self._client.request('listFolders', query={'type': type, 'parentId': parent_id})  # type: ignore[no-any-return]

    async def create(self, body: Optional[CreateFolderBody] = None, /, **fields: Any) -> Folder:
        """Create a folder.

        Required scope depends on body `type`: CAMPAIGN → `campaigns:write`, AUDIENCE → `audiences:write`,
        ACCOUNT → `accounts:write`. The body is validated before authentication, so a bad body returns 400 even
        without credentials. A duplicate name under the same parent violates a unique constraint (500).

        The JSON body can be passed as a dict, as keyword arguments, or both.

        Scope: ``campaigns:write | audiences:write | accounts:write``. HTTP: ``POST /folders``.
        """
        return await self._client.request('createFolder', body=_merge(body, fields))  # type: ignore[no-any-return]

    async def update(self, id: str, body: Optional[UpdateFolderBody] = None, /, **fields: Any) -> Folder:
        """Rename or move a folder.

        Requires `accounts:write` regardless of the folder's type.

        The JSON body can be passed as a dict, as keyword arguments, or both.

        Scope: ``accounts:write``. HTTP: ``PATCH /folders/{id}``.
        """
        return await self._client.request('updateFolder', path={'id': id}, body=_merge(body, fields))  # type: ignore[no-any-return]

    async def delete(self, id: str, /) -> Dict[str, Any]:
        """Delete a folder.

        Requires `accounts:write` regardless of type. Items inside move to root; child folders move to this folder's parent.

        Scope: ``accounts:write``. HTTP: ``DELETE /folders/{id}``.
        """
        return await self._client.request('deleteFolder', path={'id': id})  # type: ignore[no-any-return]


class AsyncResources:
    campaigns: AsyncCampaigns
    audiences: AsyncAudiences
    conversations: AsyncConversations
    accounts: AsyncAccounts
    proxies: AsyncProxies
    folders: AsyncFolders

    def _init_resources(self) -> None:
        self.campaigns = AsyncCampaigns(self)  # type: ignore[arg-type]
        self.audiences = AsyncAudiences(self)  # type: ignore[arg-type]
        self.conversations = AsyncConversations(self)  # type: ignore[arg-type]
        self.accounts = AsyncAccounts(self)  # type: ignore[arg-type]
        self.proxies = AsyncProxies(self)  # type: ignore[arg-type]
        self.folders = AsyncFolders(self)  # type: ignore[arg-type]

